ALTER TABLE public.tasks ADD CONSTRAINT tasks_title_len CHECK (char_length(title) <= 500), ADD CONSTRAINT tasks_notes_len CHECK (notes IS NULL OR char_length(notes) <= 10000);
ALTER TABLE public.notes ADD CONSTRAINT notes_title_len CHECK (char_length(title) <= 500), ADD CONSTRAINT notes_content_len CHECK (char_length(content) <= 100000);
ALTER TABLE public.habits ADD CONSTRAINT habits_name_len CHECK (char_length(name) <= 200);
ALTER TABLE public.goals ADD CONSTRAINT goals_title_len CHECK (char_length(title) <= 500), ADD CONSTRAINT goals_desc_len CHECK (description IS NULL OR char_length(description) <= 10000), ADD CONSTRAINT goals_progress_range CHECK (progress >= 0 AND progress <= 100);
ALTER TABLE public.journal_entries ADD CONSTRAINT journal_content_len CHECK (char_length(content) <= 100000), ADD CONSTRAINT journal_mood_len CHECK (mood IS NULL OR char_length(mood) <= 50);
ALTER TABLE public.daily_reviews ADD CONSTRAINT review_wins_len CHECK (wins IS NULL OR char_length(wins) <= 10000), ADD CONSTRAINT review_lessons_len CHECK (lessons IS NULL OR char_length(lessons) <= 10000), ADD CONSTRAINT review_tomorrow_len CHECK (tomorrow IS NULL OR char_length(tomorrow) <= 10000), ADD CONSTRAINT review_energy_range CHECK (energy IS NULL OR (energy >= 1 AND energy <= 5));
ALTER TABLE public.health_logs ADD CONSTRAINT health_steps_range CHECK (steps IS NULL OR (steps >= 0 AND steps <= 200000)), ADD CONSTRAINT health_sleep_range CHECK (sleep_hours IS NULL OR (sleep_hours >= 0 AND sleep_hours <= 24)), ADD CONSTRAINT health_water_range CHECK (water_glasses IS NULL OR (water_glasses >= 0 AND water_glasses <= 100)), ADD CONSTRAINT health_workout_range CHECK (workout_min IS NULL OR (workout_min >= 0 AND workout_min <= 1440));
ALTER TABLE public.ai_messages ADD CONSTRAINT ai_content_len CHECK (char_length(content) <= 20000);
ALTER TABLE public.profiles ADD CONSTRAINT profiles_display_name_len CHECK (display_name IS NULL OR char_length(display_name) <= 200), ADD CONSTRAINT profiles_vision_len CHECK (vision IS NULL OR char_length(vision) <= 5000), ADD CONSTRAINT profiles_archetype_len CHECK (archetype IS NULL OR char_length(archetype) <= 100);